// Loads what the CLI and MCP server describe: the installed package's own
// catalog.json, docs and build-time data (dist/agent-data.json, generated by
// scripts/agent-data.mjs during `npm run build`). Nothing is fetched; the data
// always matches the installed version.
import { readFileSync, existsSync } from "node:fs";
import { resolve, dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const PACKAGE_ROOT = resolve(
  dirname(fileURLToPath(import.meta.url)),
  "..",
);

const readJson = (file) => JSON.parse(readFileSync(file, "utf8"));

/** Guide topic → the shipped markdown file (and an optional section). */
export const GUIDES = {
  design: {
    file: "DESIGN.md",
    summary: "Design principles, API conventions and composing flows.",
  },
  conventions: {
    file: "DESIGN.md",
    section: "API conventions",
    summary:
      "Prop naming rules every component follows: headings, layout/variant/align, tone, state, callbacks, items, className, data attributes.",
  },
  theming: {
    file: "docs/theming.md",
    summary:
      "Brands, appearance (light/dark/system), density, runtime brandTokens and the token scales.",
  },
  "auth-flows": {
    file: "docs/auth-flows.md",
    summary:
      "Sign-in and registration: each step mapped to components, autocomplete values, validation, security and accessibility.",
  },
  "migrating-0.6": {
    file: "docs/migrating-to-0.6.md",
    summary: "Every prop and markup change from 0.5 to 0.6.",
  },
  contributing: {
    file: "CONTRIBUTING.md",
    also: ["AGENTS.md"],
    summary:
      "How to contribute a component or fix through a GitHub pull request, and the rules for coding agents.",
  },
  testing: {
    file: "TESTING.md",
    summary:
      "The component test contract: profiles, states, browser and visual checks.",
  },
  agents: {
    file: "docs/agents.md",
    summary: "How a coding agent uses Mortar with this MCP server and CLI.",
  },
};

/** One `## Heading` section of a markdown document. */
export function markdownSection(text, heading) {
  const lines = text.split("\n");
  const start = lines.findIndex((l) => l.trim() === `## ${heading}`);
  if (start < 0) return "";
  let end = lines.findIndex((l, i) => i > start && /^## /.test(l));
  if (end < 0) end = lines.length;
  return lines.slice(start, end).join("\n").trim();
}

let cached;

/**
 * The data for a package root. `root` defaults to this package; the audit
 * passes an application's installed copy when it has one.
 */
export async function loadData(root = PACKAGE_ROOT) {
  if (root === PACKAGE_ROOT && cached) return cached;
  const catalog = readJson(join(root, "catalog.json"));
  let agent;
  const built = join(root, "dist", "agent-data.json");
  if (existsSync(built)) agent = readJson(built);
  else if (existsSync(join(root, "scripts", "agent-data.mjs"))) {
    // A source checkout that has not been built yet (needs devDependencies).
    try {
      const { agentData } = await import(
        pathToFileURL(join(root, "scripts", "agent-data.mjs")).href
      );
      agent = agentData(root);
    } catch {
      agent = undefined;
    }
  }
  agent ??= {
    taxonomy: { kits: [] },
    templates: [],
    exports: { values: catalog.components.map((c) => c.export), types: [] },
    examples: {},
    inherited: {},
    inheritedSets: [],
    classes: [],
    sourceHashes: {},
    missing: true,
  };
  let principles = [];
  const principlesFile = join(root, "design-principles.json");
  if (existsSync(principlesFile))
    principles = readJson(principlesFile).principles;
  const pkg = readJson(join(root, "package.json"));
  const data = makeData({ root, catalog, agent, principles, pkg });
  if (root === PACKAGE_ROOT) cached = data;
  return data;
}

function makeData({ root, catalog, agent, principles, pkg }) {
  const components = catalog.components;
  const byId = new Map(components.map((c) => [c.id, c]));
  const byName = new Map(components.map((c) => [c.export.toLowerCase(), c]));
  // Category and kit for each component, from the playground taxonomy.
  const placement = new Map();
  for (const kit of agent.taxonomy.kits)
    for (const category of kit.categories)
      for (const name of category.components)
        placement.set(name, { kit, category });
  const kitTitle = (id) =>
    agent.taxonomy.kits.find((k) => k.id === id)?.title ?? id;
  return {
    root,
    packageName: catalog.package ?? pkg.name,
    version: catalog.version ?? pkg.version,
    catalog,
    components,
    agent,
    principles,
    /** A component by export name (any case) or catalogue id. */
    find(name) {
      if (typeof name !== "string") return undefined;
      const key = name.trim().replace(/^<|\/?>$/g, "");
      return (
        byName.get(key.toLowerCase()) ??
        byId.get(key) ??
        byId.get(`mortar-${key}`)
      );
    },
    byId: (id) => byId.get(id),
    placement(c) {
      const p = placement.get(c.export);
      return {
        kit: p?.kit.id ?? c.kitId,
        kitTitle: p?.kit.title ?? kitTitle(c.kitId),
        category: p?.category.id,
        categoryTitle: p?.category.title,
      };
    },
    /** Every prop name the component accepts, including inherited DOM attributes. */
    accepts(c) {
      const names = new Set(Object.keys(c.contract.propTypes ?? {}));
      const set = agent.inherited[c.export];
      if (set !== undefined)
        for (const n of agent.inheritedSets[set]) names.add(n);
      return names;
    },
    guide(topic) {
      const g = GUIDES[topic];
      if (!g) return undefined;
      const parts = [];
      for (const file of [g.file, ...(g.also ?? [])]) {
        const path = join(root, file);
        if (!existsSync(path)) continue;
        let text = readFileSync(path, "utf8");
        if (g.section && file === g.file)
          text = markdownSection(text, g.section);
        parts.push(text.trim());
      }
      return parts.length ? parts.join("\n\n---\n\n") : undefined;
    },
  };
}
